// Register PancakeSwap routes on the deployed adapter.
//
//   ADAPTER=0x... node scripts/configure-bnb-routes.mjs [--dry]
//
// BSC routing is not uniform — the majors have deep v3 pools against USDT, several
// assets only trade against WBNB, and a few of those are on v2 rather than v3. The
// plan in bnb-routes.json records which venue each asset needs, and was generated by
// measuring live pool balances rather than assuming a fee tier.
//
// Re-verifies every pool still holds meaningful depth before registering it, so a
// pool that has since drained is skipped instead of silently becoming a trap.

import { readFileSync } from 'node:fs'
import { createPublicClient, createWalletClient, defineChain, http, parseAbi, formatUnits } from 'viem'
import { privateKeyToAccount } from 'viem/accounts'

const ADAPTER = process.env.ADAPTER
const DRY = process.argv.includes('--dry')
if (!ADAPTER) throw new Error('set ADAPTER=0x... to the deployed PancakeAdapter')

const chain = defineChain({
  id: 56,
  name: 'BNB Chain',
  nativeCurrency: { name: 'BNB', symbol: 'BNB', decimals: 18 },
  rpcUrls: { default: { http: ['https://bsc-rpc.publicnode.com'] } },
  blockExplorers: { default: { name: 'BscScan', url: 'https://bscscan.com' } },
})

const USDT = '0x55d398326f99059fF775485246999027B3197955'
const WBNB = '0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c'
const V3F = '0x0BFbCF9fa4f9C56B0F40a671Ad40E0805A091865'
const V2F = '0xcA143Ce32Fe78f1f7019d7d551a6402fC5350c73'
/** Below this a whale pack would move the price more than the Chainlink guard allows. */
const MIN_DEPTH_USD = 40_000

const pub = createPublicClient({ chain, transport: http() })

const adapterAbi = parseAbi([
  'function setV3Single(address tokenA, address tokenB, uint24 fee)',
  'function setV3Path(address tokenIn, address tokenOut, bytes path)',
  'function setV2Path(address[] hops)',
  'function isSupported(address tokenIn, address tokenOut) view returns (bool)',
])
const f3 = parseAbi(['function getPool(address,address,uint24) view returns (address)'])
const f2 = parseAbi(['function getPair(address,address) view returns (address)'])
const erc = parseAbi(['function balanceOf(address) view returns (uint256)'])

const plan = JSON.parse(readFileSync(new URL('./bnb-routes.json', import.meta.url), 'utf8'))

/** Live depth of the pool this route's final hop depends on, in USD. */
async function depthOf(route, bnbUsd) {
  const bal = async (pool, quote) =>
    Number(formatUnits(await pub.readContract({ address: quote, abi: erc, functionName: 'balanceOf', args: [pool] }), 18))
  // Every single-hop route is USDT <-> token, WBNB included, so USDT is always the
  // side to measure. Quoting WBNB against itself just asks for a pool that cannot exist.
  if (route.venue === 'V3_SINGLE') {
    const p = await pub.readContract({ address: V3F, abi: f3, functionName: 'getPool', args: [route.token, USDT, route.fee] })
    if (p === '0x0000000000000000000000000000000000000000') return 0
    return bal(p, USDT)
  }
  if (route.venue === 'V3_PATH') {
    const p = await pub.readContract({ address: V3F, abi: f3, functionName: 'getPool', args: [route.token, WBNB, route.fee] })
    if (p === '0x0000000000000000000000000000000000000000') return 0
    return (await bal(p, WBNB)) * bnbUsd
  }
  const p = await pub.readContract({ address: V2F, abi: f2, functionName: 'getPair', args: [route.token, WBNB] })
  if (p === '0x0000000000000000000000000000000000000000') return 0
  return (await bal(p, WBNB)) * bnbUsd
}

const bnbFeed = '0x0567F2323251f0Aab15c8dFb1967E4e8A7D42aeE'
const feedAbi = parseAbi(['function latestRoundData() view returns (uint80,int256,uint256,uint256,uint80)'])
const bnbUsd = Number(formatUnits((await pub.readContract({ address: bnbFeed, abi: feedAbi, functionName: 'latestRoundData' }))[1], 8))
console.log(`BNB/USD ${bnbUsd.toFixed(2)} · adapter ${ADAPTER}${DRY ? ' · DRY RUN' : ''}\n`)

let wallet = null
if (!DRY) {
  const env = readFileSync('contracts/.env', 'utf8')
  const pk = env.match(/PRIVATE_KEY=(0x[0-9a-fA-F]{64})/)?.[1]
  if (!pk) throw new Error('PRIVATE_KEY missing from contracts/.env')
  wallet = createWalletClient({ account: privateKeyToAccount(pk), chain, transport: http() })
}

let set = 0
let skipped = 0
for (const r of plan.routes) {
  const depth = await depthOf(r, bnbUsd)
  if (depth < MIN_DEPTH_USD) {
    console.log(`SKIP ${r.sym.padEnd(6)} depth $${Math.round(depth).toLocaleString()} below floor`)
    skipped++
    continue
  }
  const label = `${r.sym.padEnd(6)} ${r.venue.padEnd(10)} $${Math.round(depth).toLocaleString()}`
  if (DRY) {
    console.log(`would set ${label}`)
    set++
    continue
  }
  let hash
  if (r.venue === 'V3_SINGLE') {
    hash = await wallet.writeContract({ address: ADAPTER, abi: adapterAbi, functionName: 'setV3Single',
      args: [USDT, r.token, r.fee] })
  } else if (r.venue === 'V3_PATH') {
    // directional: register the buy leg, then the reverse for sells
    hash = await wallet.writeContract({ address: ADAPTER, abi: adapterAbi, functionName: 'setV3Path',
      args: [USDT, r.token, r.path] })
    await pub.waitForTransactionReceipt({ hash })
    const rev = `0x${r.token.slice(2)}${r.fee.toString(16).padStart(6, '0')}${WBNB.slice(2)}${plan.usdtWbnbFee.toString(16).padStart(6, '0')}${USDT.slice(2)}`
    hash = await wallet.writeContract({ address: ADAPTER, abi: adapterAbi, functionName: 'setV3Path',
      args: [r.token, USDT, rev] })
  } else {
    hash = await wallet.writeContract({ address: ADAPTER, abi: adapterAbi, functionName: 'setV2Path', args: [r.hops] })
  }
  await pub.waitForTransactionReceipt({ hash })
  console.log(`set  ${label}  ${hash}`)
  set++
}

console.log(`\n${set} route(s) ${DRY ? 'planned' : 'registered'}, ${skipped} skipped`)
if (!DRY) {
  const live = []
  for (const r of plan.routes) {
    if (await pub.readContract({ address: ADAPTER, abi: adapterAbi, functionName: 'isSupported', args: [USDT, r.token] })) live.push(r.sym)
  }
  console.log(`adapter reports routable: ${live.join(', ')}`)
}
